import type { Config } from 'tailwindcss';

/**
 * Every colour resolves to a CSS variable rather than a literal.
 *
 * That is what makes dark mode a palette swap instead of a rewrite: the
 * variables are defined once in `src/app/theme.css` (generated by
 * `scripts/build-theme.cjs`) and redefined under `.dark`. A component written
 * as `bg-white text-slate-900 border-slate-200` therefore adapts without a
 * single `dark:` variant, because the scale is used semantically — 50 is the
 * lightest surface, 200 is a border, 900 is ink — and those relationships
 * survive inversion.
 *
 * `<alpha-value>` is the Tailwind placeholder that keeps `/50` opacity
 * modifiers working against a variable-backed colour. Without it,
 * `bg-slate-50/60` — which the zebra-stripe rule uses — would silently produce
 * an invalid colour and render nothing.
 */
const v = (name: string) => `rgb(var(--c-${name}) / <alpha-value>)`;

const scale = (name: string, steps: number[]) =>
  Object.fromEntries(steps.map((s) => [s, v(`${name}-${s}`)]));

const GREY_STEPS = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950];
const TINT_STEPS = [50, 100, 200, 300, 500, 600, 700, 800, 900, 950];

const config: Config = {
  darkMode: 'class',
  content: ['./src/**/*.{ts,tsx}'],
  theme: {
    extend: {
      colors: {
        white: v('white'),
        /**
         * Text and icons ON a saturated fill. Always white, in both themes —
         * see the note in scripts/build-theme.cjs. `text-white` on a blue
         * button is not the same thing as `bg-white` on a card, and treating
         * them as one token made the primary button unreadable at night.
         */
        onAccent: v('on-accent'),
        /**
         * A maximum-contrast solid fill and its label. Flips with the theme —
         * dark block / white text by day, light block / dark text at night —
         * because the meaning is "stands out from the page", not "is dark".
         */
        ink: v('ink'),
        onInk: v('on-ink'),
        /** Modal scrim; dark in both themes. */
        scrim: v('scrim'),
        slate: scale('slate', GREY_STEPS),
        emerald: scale('emerald', TINT_STEPS),
        amber: scale('amber', TINT_STEPS),
        rose: scale('rose', TINT_STEPS),
        sky: scale('sky', TINT_STEPS),
        brand: scale('brand', GREY_STEPS),
        gold: scale('gold', [400, 500, 600]),
      },
      fontFamily: {
        sans: ['ui-sans-serif', 'system-ui', 'Segoe UI', 'Roboto', 'Helvetica Neue', 'Arial', 'sans-serif'],
        mono: ['ui-monospace', 'SFMono-Regular', 'Menlo', 'Consolas', 'monospace'],
      },
      boxShadow: {
        // Shadows read as depth against light surfaces and as nothing against
        // dark ones, so the dark theme leans on the raised card colour instead.
        card: '0 1px 2px 0 rgb(16 24 40 / 0.06), 0 1px 3px 0 rgb(16 24 40 / 0.10)',
      },
      keyframes: {
        shimmer: {
          '100%': { transform: 'translateX(100%)' },
        },
      },
      animation: {
        shimmer: 'shimmer 1.6s infinite',
      },
    },
  },
  plugins: [],
};

export default config;
